// The full emoji set (Unicode 15.1) with Turkish + English search words. No npm package: veri-ham.ts is generated by scripts/emoji-uret.mjs.
// Tam emoji kümesi (Unicode 15.1), Türkçe + İngilizce arama kelimeleriyle. npm paketi yok: veri-ham.ts'i scripts/emoji-uret.mjs üretir.
import { HAM } from "./veri-ham";

export interface EmojiOgesi {
  emoji: string;
  /** search text: tr + en keywords, lower-cased and Turkish-folded · arama metni: tr + en kelimeler, küçük harf ve Türkçe katlamalı */
  aranan: string;
  /** takes a skin tone · ten rengi alır */
  ten: boolean;
}
export interface EmojiGrubu {
  id: keyof typeof HAM;
  /** the emoji that stands for the category tab · kategori sekmesini temsil eden emoji */
  simge: string;
  ogeler: EmojiOgesi[];
}

/** Lower-case + fold Turkish letters so "şapka" is found by "sapka" and "I" by "ı" · Küçük harfe çevir + Türkçe harfleri katla: "sapka" → "şapka" */
export function katla(s: string): string {
  return s
    .toLocaleLowerCase("tr")
    .replaceAll("ı", "i")
    .replaceAll("ş", "s")
    .replaceAll("ç", "c")
    .replaceAll("ğ", "g")
    .replaceAll("ö", "o")
    .replaceAll("ü", "u")
    .replaceAll("â", "a")
    .replaceAll("î", "i")
    .replaceAll("û", "u");
}

function oku(ham: string): EmojiOgesi[] {
  return ham
    .trim()
    .split("\n")
    .map((satir) => {
      const [ilk, aranan] = satir.split("|");
      const ten = ilk.startsWith("*");
      return { emoji: ten ? ilk.slice(1) : ilk, aranan, ten };
    });
}

// ---- Skin tones · Ten renkleri ----
export const TEN_TONLARI = ["", "🏻", "🏼", "🏽", "🏾", "🏿"];
/** The tone goes right after the first character (it replaces a variation selector) · Ton ilk karakterden hemen sonra gelir (varyasyon seçicinin yerine) */
export function tenli(emoji: string, ton: string): string {
  if (!ton) return emoji;
  const [bas, ...kalan] = [...emoji];
  return bas + ton + (kalan[0] === "\uFE0F" ? kalan.slice(1) : kalan).join("");
}

const SIMGELER: Record<keyof typeof HAM, string> = { yuzler: "😀", eller: "👍", kalpler: "❤️", hayvanlar: "🐱", yiyecek: "🍕", etkinlik: "⚽", seyahat: "🚗", nesneler: "💡", semboller: "✅", bayraklar: "🏳️" };
export const EMOJI_GRUPLARI: EmojiGrubu[] = (Object.keys(HAM) as (keyof typeof HAM)[]).map((id) => ({ id, simge: SIMGELER[id], ogeler: oku(HAM[id]) }));

/** Every emoji once, for search · Arama için her emoji bir kez */
export const TUM_EMOJILER: EmojiOgesi[] = EMOJI_GRUPLARI.flatMap((g) => g.ogeler);

/** Search: every typed word must appear in the keywords (AND), diacritics folded · Arama: yazılan her kelime anahtar kelimelerde geçmeli (VE), aksanlar katlanır */
export function emojiAra(sorgu: string, sinir = 120): EmojiOgesi[] {
  const kelimeler = katla(sorgu).split(/\s+/).filter(Boolean);
  if (kelimeler.length === 0) return [];
  // Starting-with matches first (so "kal" finds "kalp" before "takvim kalemi") · Önce başlayanlar ("kal" → "kalp", sonra diğerleri)
  const baslayan: EmojiOgesi[] = [];
  const iceren: EmojiOgesi[] = [];
  for (const e of TUM_EMOJILER) {
    if (!kelimeler.every((k) => e.aranan.includes(k))) continue;
    (kelimeler.every((k) => e.aranan.startsWith(k) || e.aranan.includes(` ${k}`)) ? baslayan : iceren).push(e);
    if (baslayan.length + iceren.length >= sinir * 2) break;
  }
  return [...baslayan, ...iceren].slice(0, sinir);
}
